def separate_paren_groups(paren_string):
    groups = []
    current_group = ""
    stack = []

    for char in paren_string:
        if char == "(":
            stack.append(char)
        elif char == ")":
            stack.pop()
            if not stack:
                groups.append(current_group)
                current_group = ""
        else:
            current_group += char

    return groups
