def max_value_on_paths(N, grid_values):
    grid = [[0] * N for _ in range(N)]
    dp = [[0] * N for _ in range(N)]
    for x, y, v in grid_values:
        grid[x][y] = v
    for i in range(N):
        dp[0][i] = grid[0][i]
        dp[i][0] = grid[i][0]
    for i in range(1, N):
        for j in range(1, N):
            dp[i][j] = max(dp[i - 1][j], dp[i][j - 1]) + grid[i][j]
    return dp[N - 1][N - 1]
```

