def decode(encoded: str, original: str, message: str) -> str:
    mapping = {}
    for i, c in enumerate(original):
        if c not in mapping:
            mapping[c] = encoded[i]
        elif mapping[c] != encoded[i]:
            return "Failed"
    decoded = []
    for c in message:
        if c not in mapping:
            return "Failed"
        decoded.append(mapping[c])
    return "".join(decoded)
