def count_partitions(n, k, x):
    dp = [[0] * (k+1) for _ in range(n+1)]
    for i in range(1, n+1):
        for j in range(1, min(i, k)+1):
            dp[i][j] = dp[i-1][j-1] + dp[i-x][j]
    return dp[n][k]
