def count_sequences(n: int, last: int, memo: dict) -> int:
    if n == 1:
        return 1
    if n not in memo:
        memo[n] = 0
        for i in range(1, int(last / 2) + 1):
            memo[n] += count_sequences(n - 1, i, memo)
    return memo[n]
