def generate_numbers(n, rules):
    visited = set()
    queue = [(n, 0)]
    while queue:
        num, depth = queue.pop(0)
        if num not in visited:
            visited.add(num)
            if depth == len(rules):
                continue
            for rule in rules:
                if str(rule[0]) in str(num):
                    queue.append((num.replace(str(rule[0]), str(rule[1])), depth + 1))
    return len(visited)
```

