def calculate_arrangements(n, m, a):
    # Initialize the dp table
    dp = [[0] * (m + 1) for _ in range(n + 1)]

    # Base case: When m = 0, there is only one arrangement (i.e., an empty arrangement)
    for i in range(n + 1):
        dp[i][0] = 1

    # Populate the dp table
    for i in range(1, n + 1):
        for j in range(1, m + 1):
            for k in range(i):
                dp[i][j] = (dp[i][j] + dp[k][j - 1]) % (10**6 + 7)

    # Return the result
    return dp[n][m]
