def minimum_students_to_leave(heights):
    n = len(heights)
    if n == 0:
        return 0
    elif n == 1:
        return 1
    else:
        i = 1
        while i < n and heights[i] >= heights[i-1]:
            i += 1
        if i == n:
            return 1
        else:
            j = i+1
            while j < n and heights[j] <= heights[j-1]:
                j += 1
            return 1 + minimum_students_to_leave(heights[:i] + heights[j:])
